-- ============================================================================
-- EC5: Capital Portfolio & Cost Control joins the catalog, the FIFTH Economics
-- course.
--
-- Catalog row (module 'economics'; path_order 57; prereq_slug NULL) plus the
-- three capstones and their eighteen graded fields, generated by
-- /root/ec-wip-portfolio/gen_course.py from fields.json and the capstone
-- constants in ec5_fields.mjs. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries the
-- route /dashboard/apps/portfolio.
--
-- THE ONE SENTENCE THE COURSE IS. Capital is allocated by funding whole
-- projects to maximise risked value under a limit, and spent against an
-- authorisation whose forecast, earned value and schedule are only as honest
-- as the rule, the date and the progress behind them.
--
-- THE ENGINES. engines/economics/portfolio.js and engines/economics/afe.js as
-- repaired in EC5-0 (engines #178): a seeded Monte Carlo risk summary with the
-- seed shown, an overshoot flag, a negative capex refused; the AFE as-of date,
-- one forecast rule, SPI null before the start, the S-curve bounded to its
-- window, negative progress refused and a negative share flagged.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('portfolio', 'Capital Portfolio & Cost Control', 'economics', 57, 'coming_soon', null)
on conflict (slug) do nothing;

